using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace Dafeiyu.Tests
{
    public static class ImageGenerationUiTests
    {
        static Application app;static PetWindow pet;static int checks;static string root;
        static void Check(bool value,string name){if(!value)throw new Exception("FAIL "+name);checks++;Console.WriteLine("PASS "+name);}
        static IEnumerable<T> All<T>(DependencyObject p)where T:DependencyObject{if(p is T)yield return(T)p;for(int i=0;i<VisualTreeHelper.GetChildrenCount(p);i++)foreach(var t in All<T>(VisualTreeHelper.GetChild(p,i)))yield return t;}
        static Button Button(DependencyObject p,string id){return All<Button>(p).Single(b=>b.Name==id);}static void Click(Button button){button.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));}
        static void Capture(Window window,string name){window.UpdateLayout();var bitmap=new RenderTargetBitmap((int)Math.Ceiling(window.ActualWidth),(int)Math.Ceiling(window.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(root,name)))encoder.Save(file);}
        sealed class Handler:HttpMessageHandler
        {
            internal TaskCompletionSource<bool> Entered=new TaskCompletionSource<bool>(),Release=new TaskCompletionSource<bool>();internal byte[] Bytes;
            protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancel){Entered.TrySetResult(true);using(cancel.Register(()=>Release.TrySetCanceled()))await Release.Task;cancel.ThrowIfCancellationRequested();return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("{\"data\":[{\"b64_json\":\""+Convert.ToBase64String(Bytes)+"\"}]}")};}
            internal void Reset(){Entered=new TaskCompletionSource<bool>();Release=new TaskCompletionSource<bool>();}
        }
        static async Task Run(string sourceImage)
        {
            root=Path.Combine(Directory.GetCurrentDirectory(),"work","image-ui-evidence");Directory.CreateDirectory(root);var cfg=new PetSettings{AutoUpdate=false,GreetingEnabled=false,AiGreetingEnabled=false,ShowPredictedMessages=false,ReadReplies=false,OnboardingState="completed",ThemeMode="light"};foreach(string id in cfg.Hotkeys.Keys.ToArray())cfg.Hotkeys[id]="";
            string data=Path.Combine(root,"data-"+Guid.NewGuid().ToString("N"));pet=new PetWindow(null,cfg,new SettingsStore(Path.Combine(data,"settings.json")),null);var chat=new ChatWindow(pet);chat.Show();await Task.Delay(100);Check(Button(chat,"ShellImages").IsVisible,"left icon rail exposes Images page");Click(Button(chat,"ShellImages"));await Task.Delay(80);Check(chat.CurrentPage=="images","Images route opens in original window");var page=All<ImageWorkspacePage>(chat).Single();Check(Button(chat,"ConfigureImageService").IsVisible,"empty workspace offers service configuration");
            Click(Button(chat,"ImageGalleryTab"));await Task.Delay(40);Click(Button(chat,"ImageGenerateTab"));await Task.Delay(40);Click(Button(chat,"ImageGalleryTab"));await Task.Delay(40);Check(All<TextBlock>(page).Any(t=>t.Text.StartsWith("图库中还没有")),"generation and gallery tabs can be revisited without reparenting errors");
            var provider=new ImageGenerationProvider{Name="Compatible test / custom model",Connection=new ConnectionSettings{BaseUrl="https://unused.invalid/v1",Model="custom-image-model"}};cfg.ImageProviders=new List<ImageGenerationProvider>{provider};cfg.ActiveImageProviderId=provider.Id;Click(Button(chat,"ShellHome"));Click(Button(chat,"ShellImages"));Click(Button(chat,"ImageGenerateTab"));await Task.Delay(50);page.UpdateLayout();Check(ReferenceEquals(All<ComboBox>(page).Single(c=>c.Name=="ImageServicePicker").SelectedItem,provider),"returning from settings resolves service from current provider list");All<TextBox>(page).Single(t=>t.Name=="ImagePrompt").Text="A blue ceramic cup";Check(!Button(chat,"ImageReferenceUpload").IsEnabled,"reference editing requires configured provider capability");
            Check(ReferenceEquals(pet.Workspaces.ImageTasks,pet.ImageTasks)&&ReferenceEquals(pet.Conversation.ImageTasks,pet.ImageTasks),"application sessions share one queue");Check(pet.Conversation.ImageConversationId.StartsWith("history:")&&!pet.Conversation.ImageConversationId.Contains(pet.Store.DirectoryPath),"standalone WPF image owner binds private stable history identity");byte[] bytes=sourceImage==null?Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAC0lEQVR4nGP4DwQACfsD/fteaysAAAAASUVORK5CYII="):File.ReadAllBytes(sourceImage);var handler=new Handler{Bytes=bytes};var client=new ImageGenerationClient(pet.ImageStore,handler,null);typeof(PetWindow).GetField("imageClient",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(pet,client);var tasks=new ImageGenerationTaskManager(new ImageGenerationTaskStore(data),pet.ImageStore,client,new ImageAssetUsageRegistry());await tasks.RestoreAsync(CancellationToken.None);typeof(PetWindow).GetField("imageTasks",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(pet,tasks);pet.Conversation.ImageTasks=tasks;pet.Workspaces.ImageTasks=tasks;var pending=page.GenerateAsync();await handler.Entered.Task;Click(Button(chat,"ShellHome"));handler.Release.TrySetResult(true);await pending;Check(chat.CurrentPage=="home"&&pet.ImageStore.List().Count==1,"generation survives navigating back to chat");Click(Button(chat,"ShellImages"));await Task.Delay(40);Click(Button(chat,"ImageGalleryTab"));await Task.Delay(60);var image=pet.ImageStore.List().Single();Check(All<ImageGalleryTile>(page).Count()==1,"gallery lists generated asset");Capture(chat,"gallery-light.png");
            ThemeManager.Apply("dark");await Task.Delay(60);Capture(chat,"gallery-dark.png");chat.Width=560;await Task.Delay(60);Capture(chat,"gallery-narrow.png");Check(Button(chat,"ImageGalleryTab").ActualWidth>0,"gallery tabs remain usable in a narrow window");chat.Width=1000;ThemeManager.Apply("light");
            All<ImageGalleryTile>(page).Single().OpenDetails();await Task.Delay(60);Check(All<Border>(chat).Any(b=>b.Name=="ChatImagePreviewOverlay"),"gallery image opens zoom and pan preview");Check(Button(chat,"ChatPreviewSaveOriginal").IsVisible&&Button(chat,"ChatPreviewCopyImage").IsVisible,"preview offers save original and bitmap copy");Capture(chat,"image-preview.png");Click(Button(chat,"ChatPreviewZoomIn"));Click(Button(chat,"ChatPreviewClose"));
            All<ImageGalleryTile>(page).Single().OpenDetails();await Task.Delay(40);Check(All<TextBox>(chat).Any(t=>t.Name=="GeneratedImageDetailPrompt"),"thumbnail click displays prompt and image metadata details");Click(Button(chat,"ChatPreviewRegenerate"));await Task.Delay(40);Check(All<TextBox>(page).Single(t=>t.Name=="ImagePrompt").Text==image.Prompt&&pet.ImageStore.List().Count==1,"regenerate prepares a new explicit request without auto charging");handler.Reset();var canceled=page.GenerateAsync();await handler.Entered.Task;Click(Button(page,"CancelImageGeneration"));await canceled;Check(pet.ImageStore.List().Count==1,"cancel produces no fake completed asset");
            await GalleryLayouts(chat,page);Click(Button(chat,"ShellHome"));ChatMessage user;var reply=pet.Conversation.History.BeginTurn("Draw a cup","text",out user);pet.Conversation.History.AttachGeneratedImage(reply.Id,image);pet.Conversation.History.Update(reply.Id,"图片已生成。","complete");chat.ReloadHistory();await Task.Delay(100);Check(All<GeneratedImageCard>(chat).Any(),"assistant reply renders an image card in chat");Capture(chat,"chat-generated-image.png");
            pet.ShowImageConfiguration();await Task.Delay(90);Check(Button(chat,"AiImageTab").IsVisible&&All<TextBox>(chat).Any(t=>t.Name=="ImageProviderModel"),"model settings exposes independent image generation tab");CheckImagePresets(chat);Capture(chat,"image-settings.png");ThemeManager.Apply("dark");await Task.Delay(50);Capture(chat,"image-settings-dark.png");chat.Width=560;await Task.Delay(60);var imageEditor=All<ImageGenerationSettings>(chat).Single();Check(Grid.GetRow(All<Border>(imageEditor).Single(b=>b.Name=="ImageProviderDetails"))==1,"narrow image configuration stacks provider rail above form");Capture(chat,"image-settings-narrow.png");chat.Width=1000;ThemeManager.Apply("light");
            handler.Reset();cfg.ImageProviders.Single(p=>p.Id==cfg.ActiveImageProviderId).Protocol="openai";var detachedPage=new ImageWorkspacePage(pet);var detachedHost=new Window{Content=detachedPage,Width=650,Height=500};detachedHost.Show();await Task.Delay(40);All<TextBox>(detachedPage).Single(t=>t.Name=="ImagePrompt").Text="survive view close";var detached=detachedPage.GenerateAsync();await handler.Entered.Task;string detachedJob=tasks.List().Last().Id;detachedPage.Dispose();detachedHost.Close();Check(!handler.Release.Task.IsCanceled&&tasks.Get(detachedJob)!=null,"ViewCloseKeepsTaskAccessible: disposing actual page does not cancel HTTP");handler.Release.TrySetResult(true);await detached;Check(tasks.Get(detachedJob).State==ImageGenerationTaskState.Succeeded,"closed page result completes in shared manager");
            handler.Reset();int imageCount=pet.ImageStore.List().Count;Click(Button(imageEditor,"TestImageGeneration"));await handler.Entered.Task;var providerList=All<ListBox>(imageEditor).Single(l=>l.Name=="ImageProviderPicker");while(providerList.Items.Count>0){app.Dispatcher.BeginInvoke(new Action(delegate{var confirm=app.Windows.OfType<Window>().Single(w=>w.Name=="RemoveImageProviderDialog");Click(Button(confirm,"ConfirmRemoveImageProvider"));}));Click(Button(imageEditor,"RemoveImageProvider"));await Task.Delay(30);}await Task.Delay(100);Check(handler.Release.Task.IsCanceled&&pet.ImageStore.List().Count==imageCount,"removing providers cancels in-flight test before hiding its controls");Check(imageEditor.Save(),"empty provider list can be saved without creating a phantom draft");
            using(var questions=new AgentQuestionController())using(var questionSurface=new AgentQuestionSurface(questions,r=>r.SessionId=="original")){var wait=questions.AskAsync(new AgentQuestionRequest{SessionId="original",TaskId="task",CallId="call",Question="Choose a target",Options=new[]{"Windows","Mac"}},CancellationToken.None);questionSurface.Refresh();var card=All<AgentQuestionCard>(questionSurface);Check(questionSurface.Visibility==Visibility.Visible,"question card waits for answer");Check(questions.Submit("original","task","call",new AgentQuestionAnswer{OptionIndex=0})&&(await wait).Text=="Windows","question answer resumes original request");}
            var waiting=pet.QuestionController.AskAsync(new AgentQuestionRequest{SessionId="closing-session",TaskId="closing-task",CallId="closing-call",Question="Wait before continuing",Options=new[]{"One","Two"}},CancellationToken.None);chat.Close();bool closedCanceled=false;try{await waiting;}catch(OperationCanceledException){closedCanceled=true;}Check(closedCanceled&&pet.QuestionController.Requests.Count==0,"closing final WPF question host cancels pending wait");Console.WriteLine("Image generation UI tests: "+checks+" passed");pet.Close();pet=null;
        }
        static byte[] LayoutPicture(int width,int height,int hue)
        {
            var visual=new DrawingVisual();using(var draw=visual.RenderOpen()){draw.DrawRectangle(new LinearGradientBrush(Color.FromRgb((byte)(40+hue*15),100,160),Color.FromRgb(200,(byte)(80+hue*12),120),45),null,new Rect(0,0,width,height));draw.DrawEllipse(new SolidColorBrush(Color.FromArgb(100,255,255,255)),null,new Point(width*.55,height*.45),width*.3,Math.Min(width,height)*.28);}
            var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=new MemoryStream()){encoder.Save(output);return output.ToArray();}
        }
        static void CheckImagePresets(ChatWindow chat)
        {
            var editor=All<ImageGenerationSettings>(chat).Single();var details=All<Expander>(editor).Single(e=>e.Name=="ImageConnectionDetails");details.IsExpanded=true;editor.UpdateLayout();var presets=All<ComboBox>(editor).Single(c=>c.Name=="ImageServicePreset");var protocol=All<ComboBox>(editor).Single(c=>c.Name=="ImageServiceProtocol");var address=All<TextBox>(editor).Single(c=>c.Name=="ImageProviderAddress");var model=All<TextBox>(editor).Single(c=>c.Name=="ImageProviderModel");var key=All<PasswordBox>(editor).Single();Check(editor.ColumnDefinitions.Count==2&&All<ListBox>(editor).Any(l=>l.Name=="ImageProviderPicker")&&All<Border>(editor).Any(b=>b.Name=="ImageProviderRail"),"image settings reuses text provider rail and detail card layout");
            var choices=presets.Items.Cast<ImageServicePreset>().ToArray();Check(choices.Length==7&&new[]{"openai","gemini","doubao","minimax","qwen","grok","custom"}.All(id=>choices.Any(p=>p.Id==id)),"image settings offers six mainstream providers and a custom preset");
            foreach(var preset in choices.Where(p=>p.Id!="custom")){key.Password="mock-key-for-old-origin";string previous=address.Text;presets.SelectedItem=preset;Check(address.Text==preset.BaseUrl&&model.Text==preset.Model&&(string)protocol.SelectedValue==preset.Protocol,"preset fills address model and native protocol: "+preset.Id);if(!ServicePresets.SameOrigin(previous,preset.BaseUrl))Check(key.Password.Length==0,"cross-origin preset clears previous key: "+preset.Id);}
            presets.SelectedItem=choices.Single(p=>p.Id=="gemini");editor.Dispatcher.BeginInvoke(new Action(delegate{var picker=app.Windows.OfType<ProviderPickerWindow>().Single();Check(All<Button>(picker).Count(b=>b.Name.StartsWith("ChooseProvider_"))==7,"image add dialog reuses seven branded provider cards");Capture(picker,"image-provider-picker.png");Click(All<Button>(picker).Single(b=>b.Name.StartsWith("ChooseProvider_")&&All<TextBlock>(b).Any(t=>t.Text=="自定义兼容服务")));}));Click(Button(editor,"AddImageProvider"));Check(presets.SelectedItem==null&&address.Text.Length==0,"new provider clears stale preset selection");presets.SelectedItem=choices.Single(p=>p.Id=="gemini");Check(address.Text==choices.Single(p=>p.Id=="gemini").BaseUrl&&(string)protocol.SelectedValue=="gemini","same preset can be reapplied to a new service");var quality=All<ComboBox>(editor).Single(c=>c.Name=="ImageProviderQuality");Check(quality.Items.Count==1&&quality.Text=="服务默认","Gemini quality options retain service default only");address.Text="https://custom-gemini.invalid/v1beta";model.Text="custom-image-model";key.Password="mock-ui-key";Click(Button(editor,"SaveImageProvider"));var saved=new SettingsStore(Path.Combine(pet.Store.DirectoryPath,"settings.json")).Load().SelectedImageProvider();Check(saved.Protocol=="gemini"&&saved.Connection.BaseUrl==address.Text&&saved.Connection.Model==model.Text,"custom address model and selected native protocol survive settings reload");
        }
        static async Task GalleryLayouts(ChatWindow chat,ImageWorkspacePage page)
        {
            int[] heights={480,220,380,180,320,500,240};for(int i=0;i<heights.Length;i++)pet.ImageStore.Save(LayoutPicture(320,heights[i],i),new GeneratedImage{Prompt="Layout sample "+i,Model="UI fixture"},true);
            Click(Button(chat,"ImageGalleryTab"));chat.Width=1220;await Task.Delay(90);Click(Button(page,"GalleryMasonryLayout"));await Task.Delay(60);var tiles=All<ImageGalleryTile>(page).ToList();Check(tiles.Count==8&&tiles.Select(t=>Math.Round(t.ActualHeight)).Distinct().Count()>2,"masonry previews retain mixed source aspect ratios");Check(tiles.All(t=>t.Child is Image),"gallery displays thumbnail-only tiles without metadata rows");Capture(chat,"gallery-masonry-light.png");
            Click(Button(page,"GalleryGridLayout"));await Task.Delay(60);tiles=All<ImageGalleryTile>(page).ToList();Check(tiles.All(t=>Math.Abs(t.ActualWidth-t.ActualHeight)<1),"uniform grid displays equal square previews");Check(tiles.All(t=>((Image)t.Child).Stretch==Stretch.UniformToFill),"grid crops only the preview to fill squares");Check(new SettingsStore(Path.Combine(pet.Store.DirectoryPath,"settings.json")).Load().ImageGalleryLayout=="grid","gallery arrangement preference survives settings reload");Capture(chat,"gallery-grid-light.png");
            ThemeManager.Apply("dark");await Task.Delay(50);Capture(chat,"gallery-grid-dark.png");Click(Button(page,"GalleryMasonryLayout"));await Task.Delay(50);Capture(chat,"gallery-masonry-dark.png");chat.Width=560;await Task.Delay(60);Capture(chat,"gallery-masonry-narrow.png");tiles=All<ImageGalleryTile>(page).ToList();Check(tiles.All(t=>t.ActualWidth<=page.ActualWidth),"thumbnail layouts stay within narrow gallery width");chat.Width=1000;ThemeManager.Apply("light");
        }
        [STAThread]public static int Main(string[] args){app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};int code=1;app.Dispatcher.BeginInvoke(new Action(async delegate{try{await Run(args.Length==1?args[0]:null);code=0;}catch(Exception e){Console.Error.WriteLine(e);}finally{foreach(var window in app.Windows.OfType<Window>().ToArray())window.Close();app.Shutdown();}}));app.Run();return code;}
    }
}
